export const ModelSupportInvestigationModal__tool_result_production_continuation_passed = ({
  strategy,
  generatedTokenCount,
  comparisonInputSource,
  inputMatch,
  firstMismatchIndex,
  cacheDecisionStatus,
  cacheDecisionReason,
  cacheProvided,
}: {
  strategy: string,
  generatedTokenCount: number,
  comparisonInputSource: string,
  inputMatch: "matched" | "mismatched",
  firstMismatchIndex: number | undefined,
  cacheDecisionStatus: string,
  cacheDecisionReason: string,
  cacheProvided: boolean,
}): string => {
  const inputSummary = (() => {
    switch (inputMatch) {
    case "matched":
      return "exakte Template-Übereinstimmung";
    case "mismatched":
      return `erste Abweichung bei ${firstMismatchIndex ?? "boundary"}`;
    default: {
      const _ex: never = inputMatch;
      throw new Error(`Unhandled input match: ${_ex}`);
    }
    }
  })();
  return `Production-Fortsetzung nach Tool-Ergebnis: ${strategy}; generiert=${generatedTokenCount} Token(s); Eingabe=${inputSummary}; Vergleich=${comparisonInputSource}; Cache=${cacheDecisionStatus} (${cacheDecisionReason}); past_key_values=${cacheProvided ? "bereitgestellt" : "nicht bereitgestellt"}; Tool-Loop-Terminierung und tatsächliche Cross-Turn-Tool-KV-Wiederverwendung nicht beobachtet`;
};
